    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'speak',17,NULL,NULL,'صندوقدار دربارهٔ رسید می‌پرسد؛ بگو رسید را داری.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"صندوقدار دربارهٔ رسید می‌پرسد؛ بگو رسید را داری.","scenario_fa":"صندوقدار دربارهٔ رسید می‌پرسد؛ بگو رسید را داری.","accepted":["Ja, ich habe den Bon.","Die Quittung ist bei mir."],"acceptedIntents":["Ja, ich habe den Bon.","Die Quittung ist bei mir."],"accepted_intents":["Ja, ich habe den Bon.","Die Quittung ist bei mir."],"input":"speech","evaluation":"stt","audioRequired":false,"textVisible":false,"scored":true,"independent":true}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',6));
    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'speak',18,NULL,NULL,'هنگام خروج بگو خرید و پرداخت تمام شده است.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"هنگام خروج بگو خرید و پرداخت تمام شده است.","scenario_fa":"هنگام خروج بگو خرید و پرداخت تمام شده است.","accepted":["Der Einkauf ist erledigt.","Alles ist bezahlt und fertig."],"acceptedIntents":["Der Einkauf ist erledigt.","Alles ist bezahlt und fertig."],"accepted_intents":["Der Einkauf ist erledigt.","Alles ist bezahlt und fertig."],"input":"speech","evaluation":"stt","audioRequired":false,"textVisible":false,"scored":true,"independent":true}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',6));
  ELSEIF v_count=1 THEN
    IF (SELECT COUNT(*) FROM lessons WHERE chapter_id=v_chapter)<>4 OR (SELECT COUNT(*) FROM turns t JOIN lessons l ON l.id=t.lesson_id WHERE l.chapter_id=v_chapter)<>47 OR (SELECT COUNT(*) FROM activities a JOIN lessons l ON l.id=a.lesson_id WHERE l.chapter_id=v_chapter)<>72 OR JSON_UNQUOTE(JSON_EXTRACT((SELECT metadata FROM chapters WHERE id=v_chapter),'$.stageId'))<>'de-fa-a1-series-0006' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Existing chapter does not match the validated stage'; END IF;
  ELSE SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chapter identity is not unique'; END IF;
  SELECT id INTO v_chapter FROM chapters WHERE module_id=v_module AND sort_order=6;
  IF (SELECT COUNT(*) FROM lessons WHERE chapter_id=v_chapter)<>4 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chapter must contain exactly four lessons'; END IF;
  IF EXISTS (SELECT 1 FROM lessons l LEFT JOIN turns t ON t.lesson_id=l.id WHERE l.chapter_id=v_chapter GROUP BY l.id HAVING COUNT(t.id)<8 OR COUNT(t.id)>14) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Turn quota failed'; END IF;
  IF EXISTS (SELECT 1 FROM lessons l LEFT JOIN activities a ON a.lesson_id=l.id WHERE l.chapter_id=v_chapter GROUP BY l.id HAVING COUNT(a.id)<>18) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Activity quota failed'; END IF;
  COMMIT;
END$$
CALL import_nova_series_006()$$
